import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_kernel_code = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_softmax_subtract_swish_max_kernel(
    const float* input,
    const float* subtract_params,
    float* output,
    int batch_size,
    int channels,
    int depth,
    int height,
    int width
) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int total_spatial = depth * height * width;
    int total_elements = batch_size * total_spatial;

    if (tid >= total_elements) return;

    int b = tid / total_spatial;
    int spatial_idx = tid % total_spatial;
    int d = spatial_idx / (height * width);
    int hw = spatial_idx % (height * width);
    int h = hw / width;
    int w = hw % width;

    const int input_offset = b * channels * total_spatial + 
                           d * channels * height * width + 
                           h * channels * width + 
                           w * channels;

    // Online softmax with max tracking
    float max_val = -INFINITY;
    float sum_exp = 0.0f;
    float buffer[32];  // Assume max 32 channels

    // First pass: compute max and sum_exp
    for(int c = 0; c < channels; ++c) {
        float val = input[input_offset + c];
        buffer[c] = val;
        max_val = fmaxf(max_val, val);
    }

    // Second pass: compute sum_exp
    for(int c = 0; c < channels; ++c) {
        sum_exp += expf(buffer[c] - max_val);
    }

    // Third pass: compute final values
    float final_max = -INFINITY;
    for(int c = 0; c < channels; ++c) {
        float softmax_val = expf(buffer[c] - max_val) / sum_exp;
        float sub_val = softmax_val - subtract_params[c];
        float swish_val = sub_val * (1.0f / (1.0f + expf(-sub_val)));
        final_max = fmaxf(final_max, swish_val);
    }

    output[tid] = final_max;
}

torch::Tensor fused_ops_cuda(torch::Tensor input, torch::Tensor subtract_params) {
    auto sizes = input.sizes();
    auto output = torch::empty({sizes[0], sizes[2], sizes[3], sizes[4]}, input.options());

    int total_elements = sizes[0] * sizes[2] * sizes[3] * sizes[4];
    int threads = 256;
    int blocks = (total_elements + threads - 1) / threads;

    fused_softmax_subtract_swish_max_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        subtract_params.data_ptr<float>(),
        output.data_ptr<float>(),
        sizes[0],
        sizes[1],
        sizes[2],
        sizes[3],
        sizes[4]
    );

    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("fused_ops_cuda", &fused_ops_cuda, "Fused Softmax-Subtract-Swish-Max Kernel");
}
"""

cpp_wrapper = "torch::Tensor fused_ops_cuda(torch::Tensor input, torch::Tensor subtract_params);"

fused_ops = load_inline(
    name='fused_ops',
    cpp_sources=cpp_wrapper,
    cuda_sources=fused_kernel_code,
    functions=['fused_ops_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, pool_kernel_size, pool_stride, pool_padding):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, 
                                                stride=stride, padding=padding, 
                                                output_padding=output_padding)
        self.max_pool = nn.MaxPool3d(kernel_size=pool_kernel_size, 
                                    stride=pool_stride, 
                                    padding=pool_padding)
        self.subtract = nn.Parameter(torch.randn(out_channels))

    def forward(self, x):
        x = self.conv_transpose(x)
        x = self.max_pool(x)
        x = x.contiguous()
        return fused_ops.fused_ops_cuda(x, self.subtract)
